import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.Cdl20cf0.js";const u=JSON.parse('{"title":"Experimental AirPlay 2 bridge","description":"","frontmatter":{},"headers":[],"relativePath":"deployment-airplay2.md","filePath":"deployment-airplay2.md","lastUpdated":1793247657000}'),n={name:"deployment-airplay2.md"};function r(o,e,l,d,p,h){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="experimental-airplay-2-bridge" tabindex="-1">Experimental AirPlay 2 bridge <a class="header-anchor" href="#experimental-airplay-2-bridge" aria-label="Permalink to &quot;Experimental AirPlay 2 bridge&quot;">​</a></h1><p>This opt-in receiver uses Shairport Sync 5.5.2 and NQPTP 1.2.8 to feed 48 kHz, S16LE, stereo PCM into an HTTP WAV stream pulled by one selected Xiaomi speaker. Other speakers retain AirPlay 1; DLNA remains available.</p><p>Shairport handles pairing, buffered audio, and receiver-side PTP timing. A small stdout extension preserves planned playback times and session boundaries. The HTTP bridge schedules audio against those timestamps using Linux <code>CLOCK_MONOTONIC_RAW</code>.</p><p>Xiaomi&#39;s HTTP player exposes neither its DAC clock nor buffer depth. <strong>Acoustic synchronization with HomePod or other receivers has not been verified.</strong> Output latency is a manual estimate, not hardware clock feedback.</p><h2 id="install-or-update" tabindex="-1">Install or update <a class="header-anchor" href="#install-or-update" aria-label="Permalink to &quot;Install or update&quot;">​</a></h2><p>The standard <code>mrdeer1997/miair-next:latest</code> image includes Shairport Sync and NQPTP on both amd64 and arm64. Use the existing <a href="./deployment.html">installation instructions</a>, including the one-command installer, standard Compose, fnOS, or iStore deployment. No separate AirPlay 2 image or source build is required. Use a Linux host with host networking; Docker Desktop on Windows/macOS cannot provide the required LAN multicast path.</p><p>For an existing installation, update through its normal container management flow. With <code>manage.sh</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./manage.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>For the standard Compose deployment:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Keep the existing data mount. Updates preserve accounts, enabled speakers and protocol settings. AirPlay 1 remains the default until AirPlay 2 is enabled in service settings. A successful main-branch image workflow updates <code>latest</code>; simply merging code does not update an already-running container. Version tags also publish versioned images and a GitHub Release. The panel&#39;s release checker detects those releases, not every main-branch image.</p><p>Allow the Web and DLNA ports (8300/8200 by default), AirPlay TCP 7000, mDNS UDP 5353, dynamically allocated HTTP audio ports, and PTP UDP 319/320. NQPTP also uses local UDP 9000. Conflicting PTP services must be stopped first. Keep the container&#39;s private IPC namespace; do not mount the host&#39;s <code>/run</code> or use <code>--ipc=host</code>.</p><p>The standard image starts discovery daemons before delegating to the existing privilege-drop entrypoint. The backend, Shairport Sync, and NQPTP run as <code>miair</code>; NQPTP receives only the file capability needed to bind low-numbered PTP ports. Avahi uses its own default privilege drop. No privileged-container mode or extra Docker capability is required.</p><p>On hosts with multiple interfaces, set <code>MIAIR_AIRPLAY_INTERFACE</code> to the LAN interface reported by <code>ip link</code> (for example <code>br-lan</code>). The backend&#39;s advertised address must remain reachable from the speaker.</p><h3 id="optional-source-build-testing" tabindex="-1">Optional source-build testing <a class="header-anchor" href="#optional-source-build-testing" aria-label="Permalink to &quot;Optional source-build testing&quot;">​</a></h3><p>The default Docker build includes both receiver implementations:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> miair-next:local</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>To test with an isolated data directory, stop any existing MiAir container first, preserve its data, and set the reachable LAN address:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MIAIR_HOSTNAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host-LAN-IP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.airplay2.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div><p>This development Compose file retains the <code>airplay2</code> build target and separate <code>data-airplay2-test</code> directory. It is optional; normal installations use the standard image and their existing data directory.</p><h2 id="settings-and-calibration" tabindex="-1">Settings and calibration <a class="header-anchor" href="#settings-and-calibration" aria-label="Permalink to &quot;Settings and calibration&quot;">​</a></h2><p>Open the Web UI at the configured host and port. Configure a Xiaomi account, enable speakers, then turn on <strong>为一个音箱启用 AirPlay 2（实验性）</strong> under service settings and choose one target speaker. Other enabled speakers continue to use AirPlay 1. Save to restart the services. AirPlay settings use Simplified Chinese, following the upstream interface. <code>MIAIR_AIRPLAY_MODE</code> supplies a default for new configurations; saved settings take precedence.</p><p>The output latency estimate accepts 0–4000 ms. Increasing it sends audio earlier; decreasing it sends audio later. The default 1000 ms is a nominal estimate, not a measurement. Apply a latency change and reconnect the sender before comparing against another receiver. The latency-only save preserves other unsaved form fields. Input precision of 1 ms does not imply acoustic accuracy of 1 ms.</p><p>Buffered audio must arrive far enough ahead to meet the requested lead. When it does not, the bridge retains unexpired audio and reports the shortfall. A larger setting cannot compensate for audio not yet received or varying firmware buffers. Startup may skip expired audio, including a small part of a track&#39;s beginning.</p><h2 id="behavior-and-limits" tabindex="-1">Behavior and limits <a class="header-anchor" href="#behavior-and-limits" aria-label="Permalink to &quot;Behavior and limits&quot;">​</a></h2><ul><li>One AirPlay 2 receiver per host IP; other enabled speakers use AirPlay 1. A sender may also select receivers on other IPs.</li><li>PCM is software-volume controlled by Shairport. Hardware volume is not synchronized bidirectionally.</li><li>Sender-provided track information and JPEG/PNG artwork appear in the dashboard. Metadata uses Shairport&#39;s separate FIFO, leaving timed PCM unchanged. Artwork is held in memory (up to 4 MiB), requires panel authentication, and expires when replaced or disconnected. Apps that omit metadata cannot supply these details.</li><li>Enable <strong>Touchscreen lyrics</strong> in display settings to match AirPlay 2 titles/artists against Xiaomi&#39;s catalog asynchronously. Supported touchscreen speakers obtain catalog lyrics and cover art via the matched audioID; this does not send the sender&#39;s image or lyric text to the Xiaomi screen. An unavailable match falls back to the configured default audioID. Matching and track changes may briefly rebuffer the HTTP player, as with the existing AirPlay 1 lyrics path.</li><li>Home App provisioning and video are unavailable.</li><li>Pause, immediate flush, and stop retire the old WAV URL and connection. Resume creates a new URL and reissues the Xiaomi play command, which can briefly rebuffer. Deferred flush does not immediately stop playback.</li><li>Control boundaries use level 2 messages from the pinned Shairport version, plus in-band stdout epochs. Revalidate both when upgrading it. The adapter must not enable <code>MIAIR_AIRPLAY2_TIMED_STDOUT</code> with an unpatched binary.</li><li>Each WAV session has one consumer. Old URLs return 410 while another session is active; HEAD does not consume PCM. The bridge adds no synthetic silence during gaps.</li><li>Timestamp discontinuities, delivery stalls, and HTTP failures may rebuild the downstream stream. Recovery is rate-limited to once per three seconds. This detects server-side timing faults, not pauses confined to the speaker&#39;s internal player.</li><li>Startup failure falls back to AirPlay 1 and exposes the error. Runtime exit stops both native processes and the HTTP bridge; save settings or restart to retry. A Web health check alone does not establish AirPlay 2 readiness.</li></ul><h2 id="verification-and-rollback" tabindex="-1">Verification and rollback <a class="header-anchor" href="#verification-and-rollback" aria-label="Permalink to &quot;Verification and rollback&quot;">​</a></h2><p>Test discovery, initial playback, software volume/mute, pause/resume, track changes, repeated seeks, disconnect/reconnect, and container restart on the intended sender and speaker. Compare initial and continuous acoustic output against another receiver, including after seeks; simultaneous selection alone does not establish synchronization.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> miair-next</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> miair-next</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shairport-sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -V</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> miair-next</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nqptp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -V</span></span></code></pre></div><p>Enable debug application logging for native process details. Preserve and redact logs before sharing. The status page reports process liveness and startup/runtime errors, not measured acoustic alignment.</p><p>AirPlay 2 audio diagnostics expose the HTTP bridge&#39;s client count, PCM queue depth and sample format. Native Shairport RTP/decoder counters are unavailable through this adapter and are omitted; the dashboard only shows metrics supplied by the active receiver.</p><p>To return all speakers to AirPlay 1, turn off <strong>为一个音箱启用 AirPlay 2（实验性）</strong> and save. For isolated source-build testing, stop the test container before restarting the previous installation. Neither action requires deleting data.</p><p>References: <a href="https://github.com/mikebrady/shairport-sync/blob/5.5.2/AIRPLAY2.md" target="_blank" rel="noreferrer">Shairport Sync AirPlay 2</a>, <a href="https://github.com/mikebrady/shairport-sync/releases/tag/5.5.2" target="_blank" rel="noreferrer">Shairport Sync 5.5.2</a>, <a href="https://github.com/mikebrady/nqptp/tree/1.2.8" target="_blank" rel="noreferrer">NQPTP 1.2.8</a>.</p>`,33)])])}const k=a(n,[["render",r]]);export{u as __pageData,k as default};
